constraints:
1 ≤ K ≤ 10^{4}
1 ≤ N ≤ 10^{5}
1 ≤ Arr[i] ≤ 10^{5}

expected time complexity: O(N*logN)
expected auxiliary space: O(N)

standard_solution_code:
class Solution:

	def getMinDiff(self, arr, n, k):
		arr.sort()
		ans = arr[-1] - arr[0]
		for i in range(1, n):
			if arr[i] - k < 0:
				continue
			max_ = max(arr[i - 1] + k, arr[-1] - k)
			min_ = min(arr[i] - k, arr[0] + k)
			ans = min(ans, max_ - min_)
		return ans
